  if (initialized) return;
  initialized = true;

  const now = new Date().toISOString();
  for (const seed of COMPANY_MEMORY_SEED) {
    const record: IVXMemoryRecord = {
      ...seed,
      id: randomUUID(),
      createdAt: now,
      updatedAt: now,
    };
    memoryStore.set(record.id, record);
  }
}

