  markers.push('phase13_business_reasoning');

  return {
    taskId,
    traceId,
    response: finalResponse,
    serializedResponse: serializeResponse(finalResponse),
    classification,
    modelRouting,
    contextPackage,
    securityScan,
    plan,
    specialists,
    uncertainty,
    critique,
    conversationState,
